const V=[[1,0],[3,0],[4,2],[2.5,3.5],[0.5,2.5],[0,1]];
const adj=[[1,5],[0,2],[1,3],[2,4],[3,5],[4,0]];
const c=[1,1.2];
function obj(i){return c[0]*V[i][0]+c[1]*V[i][1];}
const PATH=[0];(function(){var cur=0;while(true){var best=cur,bv=obj(cur);for(var n=0;n<adj[cur].length;n++){var nb=adj[cur][n];if(obj(nb)>bv+1e-9){bv=obj(nb);best=nb;}}if(best===cur)break;PATH.push(best);cur=best;}})();
const K=PATH.length-1;
function px(x){return 140+x*82;}function py(y){return 325-y*82;}
function frame(t){
  while(G.firstChild)G.removeChild(G.firstChild);
  var k=Math.round(t*K);
  var pd='';for(var i=0;i<V.length;i++)pd+=(i?'L':'M')+px(V[i][0]).toFixed(1)+' '+py(V[i][1]).toFixed(1)+' ';pd+='Z';
  G.appendChild(SVG('path',{d:pd,fill:'var(--cyan)','fill-opacity':0.10,stroke:'var(--mute)','stroke-width':1.5}));
  for(var i=0;i<V.length;i++)G.appendChild(SVG('circle',{cx:px(V[i][0]),cy:py(V[i][1]),r:3,fill:'var(--mute)'}));
  var cv=V[PATH[k]];
  var dlx=-c[1],dly=c[0],s=2.4;
  G.appendChild(SVG('line',{x1:px(cv[0]-dlx*s),y1:py(cv[1]-dly*s),x2:px(cv[0]+dlx*s),y2:py(cv[1]+dly*s),stroke:'var(--violet)','stroke-width':1.5,'stroke-dasharray':'5 4',opacity:0.85}));
  var wd='';for(var i=0;i<=k;i++)wd+=(i?'L':'M')+px(V[PATH[i]][0]).toFixed(1)+' '+py(V[PATH[i]][1]).toFixed(1)+' ';
  if(k>0)G.appendChild(SVG('path',{d:wd,fill:'none',stroke:'var(--yellow)','stroke-width':3,'stroke-linejoin':'round'}));
  for(var i=0;i<=k;i++)G.appendChild(SVG('circle',{cx:px(V[PATH[i]][0]),cy:py(V[PATH[i]][1]),r:5,fill:'var(--yellow)'}));
  G.appendChild(SVG('circle',{cx:px(cv[0]),cy:py(cv[1]),r:7,fill:'var(--cyan)',stroke:'var(--bg)','stroke-width':1.5}));
  var bx=0.15,by=2.7;
  G.appendChild(SVG('line',{x1:px(bx),y1:py(by),x2:px(bx+c[0]*0.5),y2:py(by+c[1]*0.5),stroke:'var(--green)','stroke-width':2.5}));
  var al=SVG('text',{x:px(bx+c[0]*0.5)+6,y:py(by+c[1]*0.5),'font-size':13,fill:'var(--green)'});al.textContent='max c\u00b7x';G.appendChild(al);
  var optimal=(k===K);
  out.innerHTML='pivot '+k+' / '+K+' &nbsp;\u00b7&nbsp; vertex ('+cv[0]+', '+cv[1]+') &nbsp;\u00b7&nbsp; c\u00b7x = '+obj(PATH[k]).toFixed(2)+' &nbsp;\u00b7&nbsp; '+(optimal?'optimal \u2014 no adjacent vertex improves c\u00b7x':'climbing to a better adjacent vertex');
}

const svg = $('#flow-svg'), out = $('#flow-out');
const btnReset = $('#flow-reset'), btnAuto = $('#flow-auto'), btnMin = $('#flow-mincut');
/* small grid network: s, a, b, c, d, t.
   Edges with capacities (we'll display as flow/cap and tick after augmentation): */
const V = ['s','a','b','c','d','t'];
const POS = { s:[60,140], a:[200,60], b:[200,220], c:[400,60], d:[400,220], t:[560,140] };
let E = [
  {u:'s', v:'a', cap:4, flow:0},
  {u:'s', v:'b', cap:5, flow:0},
  {u:'a', v:'c', cap:3, flow:0},
  {u:'a', v:'b', cap:2, flow:0},
  {u:'b', v:'d', cap:4, flow:0},
  {u:'c', v:'t', cap:5, flow:0},
  {u:'c', v:'d', cap:2, flow:0},
  {u:'d', v:'t', cap:3, flow:0},
];
let showCut = false;
function reset(){
  for(const e of E) e.flow=0;
  showCut=false;
  draw();
}
function residualBFS(){
  const adj = {}; for(const u of V) adj[u]=[];
  for(const e of E){
    if(e.flow < e.cap) adj[e.u].push({to:e.v, e, dir:1, slack:e.cap-e.flow});
    if(e.flow > 0)     adj[e.v].push({to:e.u, e, dir:-1, slack:e.flow});
  }
  const prev = {s:null}; const Q=['s'];
  while(Q.length){
    const u=Q.shift();
    if(u==='t') break;
    for(const {to,e,dir,slack} of adj[u]){
      if(prev[to]===undefined){ prev[to]={u,e,dir,slack}; Q.push(to); }
    }
  }
  if(prev.t===undefined) return null;
  /* trace path */
  const path = [];
  let cur='t';
  while(cur!=='s'){
    const p = prev[cur];
    path.push({...p, v:cur});
    cur = p.u;
  }
  path.reverse();
  const bottleneck = Math.min(...path.map(p=>p.slack));
  return {path, bottleneck};
}
function augment(){
  const r = residualBFS();
  if(!r){ out.textContent = `No augmenting path. Max flow = ${flowVal()}.  Click "show min cut" for the witness.`; return; }
  for(const p of r.path){
    p.e.flow += p.dir<0 ? -r.bottleneck : r.bottleneck;
  }
  showCut=false;
  draw();
  out.textContent = `Augmented along s → ${r.path.map(p=>p.v).join(' → ')} by ${r.bottleneck}. |f| = ${flowVal()}.`;
}
function flowVal(){ let s=0; for(const e of E) if(e.u==='s') s += e.flow; return s; }
function minCut(){
  /* Max-flow / min-cut only certifies optimality after augmentations are exhausted.
     Auto-run to completion (silently, no per-step UI churn) so the cut we report really is minimum. */
  let autoSteps = 0;
  while(true){
    const r = residualBFS();
    if(!r) break;
    for(const p of r.path){
      p.e.flow += p.dir<0 ? -r.bottleneck : r.bottleneck;
    }
    autoSteps++;
    if(autoSteps > 1000){ out.textContent = 'Auto-augment safety cap (1000 steps) hit before the residual was exhausted; the cut below is NOT certified minimum. Please file a bug.'; return; }
  }
  /* reachable set in residual from s */
  const adj = {}; for(const u of V) adj[u]=[];
  for(const e of E){
    if(e.flow < e.cap) adj[e.u].push(e.v);
    if(e.flow > 0)     adj[e.v].push(e.u);
  }
  const seen = new Set(['s']); const Q=['s'];
  while(Q.length){ const u=Q.shift(); for(const v of adj[u]) if(!seen.has(v)){ seen.add(v); Q.push(v); } }
  const S = [...seen], T = V.filter(u=>!seen.has(u));
  const cutEdges = E.filter(e=>seen.has(e.u) && !seen.has(e.v));
  showCut={S,T,cutEdges};
  draw();
  const prefix = autoSteps > 0 ? `Auto-augmented ${autoSteps} path${autoSteps===1?'':'s'} to optimality. ` : '';
  out.textContent = `${prefix}Min cut: S = {${S.join(', ')}}, T = {${T.join(', ')}}. Capacity = ${cutEdges.reduce((s,e)=>s+e.cap,0)} = |f| = ${flowVal()}.`;
}
function draw(){
  svg.innerHTML='';
  /* edges */
  for(const e of E){
    const [x1,y1]=POS[e.u], [x2,y2]=POS[e.v];
    const isCutEdge = showCut && showCut.cutEdges && showCut.cutEdges.includes(e);
    const stroke = isCutEdge ? 'var(--pink)' : (e.flow>0 ? 'var(--cyan)' : 'var(--mute)');
    const sw = isCutEdge ? 3 : (e.flow>0 ? 2 : 1.2);
    svg.appendChild(SVG('line',{x1,y1,x2,y2,stroke,'stroke-width':sw,'data-edge':`${e.u}-${e.v}`,style:'cursor:pointer'}));
    /* label at midpoint */
    const mx=(x1+x2)/2, my=(y1+y2)/2;
    const lbl = SVG('text',{x:mx,y:my-6,'text-anchor':'middle','font-size':11,fill:'var(--ink)'});
    lbl.textContent = `${e.flow}/${e.cap}`;
    svg.appendChild(lbl);
  }
  /* nodes */
  for(const v of V){
    const [x,y] = POS[v];
    const inS = showCut && showCut.S && showCut.S.includes(v);
    const inT = showCut && showCut.T && showCut.T.includes(v);
    const fill = inS ? 'color-mix(in srgb, var(--cyan) 35%, var(--panel2))' :
                 inT ? 'color-mix(in srgb, var(--pink) 35%, var(--panel2))' : 'var(--panel2)';
    const stroke = (v==='s' || v==='t') ? 'var(--yellow)' : 'var(--ink)';
    svg.appendChild(SVG('circle',{cx:x,cy:y,r:18,fill,stroke,'stroke-width':1.5}));
    const t = SVG('text',{x,y:y+5,'text-anchor':'middle','font-size':14,fill:'var(--ink)','font-weight':600});
    t.textContent = v; svg.appendChild(t);
  }
  if(!out.textContent) out.textContent = `|f| = ${flowVal()}. Click "find augmenting path" to push flow along one BFS path.`;
}
svg.addEventListener('click', ev=>{
  const tgt = ev.target;
  if(tgt && tgt.getAttribute && tgt.getAttribute('data-edge')){
    /* augment along path through this edge (best effort: just call augment) */
    augment();
  }
});
btnReset.addEventListener('click', ()=>{ reset(); out.textContent = 'Flow reset to zero.'; });
btnAuto.addEventListener('click', augment);
btnMin.addEventListener('click', minCut);
reset();

const svg = $('#match-svg'), out = $('#match-out');
const btnReset = $('#match-reset'), btnStep = $('#match-step'), btnCover = $('#match-cover');
/* Bipartite graph L = {l1..l4}, R = {r1..r4} with these edges. */
const L = ['l1','l2','l3','l4'];
const R = ['r1','r2','r3','r4'];
const POS = {
  l1:[160,40], l2:[160,120], l3:[160,200], l4:[160,260],
  r1:[480,40], r2:[480,120], r3:[480,200], r4:[480,260],
};
const EDGES = [
  ['l1','r1'],['l1','r2'],
  ['l2','r1'],['l2','r3'],
  ['l3','r2'],['l3','r3'],['l3','r4'],
  ['l4','r4'],
];
let M = new Set(); /* set of "u-v" strings, matched edges */
let cover = null;  /* min vertex cover after computation */
function reset(){ M = new Set(); cover=null; draw(); }
function matchedPartner(u){
  for(const e of M){
    const [a,b]=e.split('-');
    if(a===u) return b;
    if(b===u) return a;
  }
  return null;
}
function augmentStep(){
  cover=null;
  /* find an unmatched left vertex, BFS for alternating path to unmatched right. */
  for(const u of L){
    if(matchedPartner(u)!==null) continue;
    const prev = {[u]:null};
    const Q = [u];
    let endpoint=null;
    while(Q.length){
      const x = Q.shift();
      if(L.includes(x)){
        /* take non-matching edges to right */
        for(const [a,b] of EDGES){
          const r = a===x?b:(b===x?a:null);
          if(!r) continue;
          const edgeKey = `${x}-${r}`, rev = `${r}-${x}`;
          if(M.has(edgeKey) || M.has(rev)) continue;
          if(prev[r]===undefined){
            prev[r] = {from:x, edge:edgeKey};
            if(matchedPartner(r)===null){ endpoint=r; Q.length=0; break; }
            Q.push(r);
          }
        }
      } else {
        /* x is right — take matching edge */
        const partner = matchedPartner(x);
        if(partner && prev[partner]===undefined){
          prev[partner] = {from:x, edge:`${x}-${partner}`};
          Q.push(partner);
        }
      }
    }
    if(endpoint){
      /* flip path */
      let cur = endpoint;
      const flips=[];
      while(prev[cur]){
        flips.push(prev[cur].edge);
        cur = prev[cur].from;
      }
      for(const e of flips){
        const rev = e.split('-').reverse().join('-');
        if(M.has(e)) M.delete(e);
        else if(M.has(rev)) M.delete(rev);
        else M.add(e);
      }
      draw();
      out.textContent = `Augmenting path from ${u} to ${endpoint}: flipped ${flips.length} edges. |M| = ${M.size}.`;
      return;
    }
  }
  out.textContent = `No augmenting path remains. Maximum matching of size ${M.size}.`;
}
function showCover(){
  /* König–Egerváry only certifies |M| = |cover| once no augmenting path remains.
     Auto-run augmentations to completion (silently) before computing the cover. */
  let autoSteps = 0;
  while(true){
    const before = M.size;
    augmentStep();
    if(M.size === before) break;
    autoSteps++;
    if(autoSteps > 1000){ out.textContent = 'Auto-augment safety cap (1000 steps) hit before maximum matching was reached; the cover below is NOT certified minimum. Please file a bug.'; return; }
  }
  /* König: from the residual reachability, compute min vertex cover.
     Z = unmatched-left ∪ {reachable via alt paths}.  Cover = (L\Z) ∪ (R∩Z).
     Here we approximate by BFS in the same alternating graph. */
  const Z = new Set();
  for(const u of L) if(matchedPartner(u)===null){ Z.add(u); }
  let changed = true;
  while(changed){
    changed=false;
    for(const v of [...Z]){
      if(L.includes(v)){
        for(const [a,b] of EDGES){
          const r = a===v?b:(b===v?a:null);
          if(!r) continue;
          const key = `${v}-${r}`, rev = `${r}-${v}`;
          if(M.has(key)||M.has(rev)) continue;
          if(!Z.has(r)){ Z.add(r); changed=true; }
        }
      } else {
        const p = matchedPartner(v);
        if(p && !Z.has(p)){ Z.add(p); changed=true; }
      }
    }
  }
  const C = new Set();
  for(const u of L) if(!Z.has(u)) C.add(u);
  for(const r of R) if(Z.has(r)) C.add(r);
  cover = C;
  draw();
  const prefix = autoSteps > 0 ? `Auto-augmented ${autoSteps} path${autoSteps===1?'':'s'} to maximum matching. ` : '';
  out.textContent = `${prefix}Min vertex cover: {${[...C].join(', ')}}, size ${C.size}. By König–Egerváry this equals |M| = ${M.size}.`;
}
function draw(){
  svg.innerHTML='';
  /* edges */
  for(const [a,b] of EDGES){
    const matched = M.has(`${a}-${b}`) || M.has(`${b}-${a}`);
    svg.appendChild(SVG('line',{
      x1:POS[a][0], y1:POS[a][1], x2:POS[b][0], y2:POS[b][1],
      stroke: matched ? 'var(--yellow)' : 'var(--mute)',
      'stroke-width': matched ? 3 : 1.2,
    }));
  }
  /* nodes */
  for(const v of [...L, ...R]){
    const inCover = cover && cover.has(v);
    svg.appendChild(SVG('circle',{
      cx:POS[v][0], cy:POS[v][1], r:18,
      fill: inCover ? 'color-mix(in srgb, var(--pink) 35%, var(--panel2))' : 'var(--panel2)',
      stroke: L.includes(v) ? 'var(--cyan)' : 'var(--violet)',
      'stroke-width': 1.6,
    }));
    const t = SVG('text',{x:POS[v][0], y:POS[v][1]+5, 'text-anchor':'middle','font-size':13,fill:'var(--ink)','font-weight':600});
    t.textContent=v; svg.appendChild(t);
  }
  /* legend */
  const lg = SVG('g',{transform:'translate(20, 20)'});
  const t1 = SVG('text',{x:0,y:0,'font-size':10,fill:'var(--mute)'}); t1.textContent='cyan ring = left part'; lg.appendChild(t1);
  const t2 = SVG('text',{x:0,y:14,'font-size':10,fill:'var(--mute)'}); t2.textContent='violet ring = right part'; lg.appendChild(t2);
  const t3 = SVG('text',{x:0,y:28,'font-size':10,fill:'var(--mute)'}); t3.textContent='yellow edge = matched'; lg.appendChild(t3);
  const t4 = SVG('text',{x:0,y:42,'font-size':10,fill:'var(--mute)'}); t4.textContent='pink fill = vertex cover'; lg.appendChild(t4);
  svg.appendChild(lg);
  if(!out.textContent) out.textContent = `Matching size |M| = ${M.size}. Click "next augmenting path".`;
}
btnReset.addEventListener('click', ()=>{ reset(); out.textContent='Matching reset.'; });
btnStep.addEventListener('click', augmentStep);
btnCover.addEventListener('click', showCover);
reset();

const svg = $('#poly-svg'), out = $('#poly-out');
const btnPrev = $('#poly-prev'), btnNext = $('#poly-next'), step = $('#poly-step-out');
let s = 0;
const STEPS = [
  {
    title:'Step 0: LP relaxation with degree constraints only',
    text:'On the 5-cycle C₅, the LP relaxation {x ≥ 0, Σ_{e∋v} x_e ≤ 1} has fractional optimum x_e = 1/2 on every edge, giving Σ x_e = 5/2 — but no integer matching exceeds 2.',
    x:[0.5,0.5,0.5,0.5,0.5],
    bound:'∑ x_e ≤ 5/2 (fractional)',
  },
  {
    title:'Step 1: add the odd-set inequality on V(C₅)',
    text:'For the odd set S=V (size 5), Edmonds\' inequality is Σ_{e⊆S} x_e ≤ ⌊5/2⌋ = 2. Add this constraint.',
    x:[0.5,0.5,0.5,0.5,0.5],
    bound:'Σ x_e ≤ 2 (forced by odd-set on V)',
  },
  {
    title:'Step 2: LP relaxation now respects the odd-set bound',
    text:'The LP fractional optimum drops to 2 — matching the integer hull. Any extreme point now has every x_e ∈ {0, 1}.',
    x:[1,0,1,0,0],
    bound:'∑ x_e = 2 (integer optimum)',
  },
  {
    title:'Step 3: equivalence with the matching polytope',
    text:'Adding the odd-set inequality for every odd S ⊆ V (only V here, but in larger graphs there are exponentially many) yields exactly Edmonds\' matching polytope description.',
    x:[1,0,1,0,0],
    bound:'matching polytope = degree + odd-set constraints',
  },
];
function draw(){
  svg.innerHTML='';
  const cur = STEPS[s];
  step.textContent = `step ${s} / ${STEPS.length-1}`;
  /* draw 5-cycle */
  const cx=200, cy=160, r=110;
  const V=[];
  for(let k=0;k<5;k++){
    const a = -Math.PI/2 + 2*Math.PI*k/5;
    V.push([cx + r*Math.cos(a), cy + r*Math.sin(a)]);
  }
  /* edges with thickness ∝ x_e */
  for(let k=0;k<5;k++){
    const [x1,y1]=V[k], [x2,y2]=V[(k+1)%5];
    const w = cur.x[k];
    const thickness = 1 + w*7;
    const col = w>=1-1e-6 ? 'var(--yellow)' : (w<=1e-6 ? 'var(--mute)' : 'var(--cyan)');
    svg.appendChild(SVG('line',{x1,y1,x2,y2,stroke:col,'stroke-width':thickness,opacity:w>1e-6?1:0.4}));
    const mx=(x1+x2)/2 + (V[k][0]-cx)*0.15, my=(y1+y2)/2 + (V[k][1]-cy)*0.15;
    const t = SVG('text',{x:mx,y:my+4,'text-anchor':'middle','font-size':11,fill:'var(--ink)'});
    t.textContent = w.toFixed(2); svg.appendChild(t);
  }
  /* nodes */
  for(let k=0;k<5;k++){
    svg.appendChild(SVG('circle',{cx:V[k][0],cy:V[k][1],r:14,fill:'var(--panel2)',stroke:'var(--ink)','stroke-width':1.4}));
    const t = SVG('text',{x:V[k][0],y:V[k][1]+5,'text-anchor':'middle','font-size':12,fill:'var(--ink)'});
    t.textContent = `v${k+1}`; svg.appendChild(t);
  }
  /* annotation panel right */
  const panel = SVG('g',{transform:'translate(380, 30)'});
  const r1 = SVG('rect',{x:0,y:0,width:240,height:260,fill:'var(--panel2)',stroke:'var(--line)',rx:6});
  panel.appendChild(r1);
  const ttl = SVG('text',{x:12,y:24,'font-size':13,fill:'var(--ink)','font-weight':600});
  ttl.textContent = cur.title; panel.appendChild(ttl);
  /* wrap text */
  const words = cur.text.split(' ');
  let line='', lineNo=0;
  for(const w of words){
    const test = (line?line+' ':'')+w;
    if(test.length>32 && line){
      const t = SVG('text',{x:12,y:48+lineNo*15,'font-size':11,fill:'var(--mute)'});
      t.textContent = line; panel.appendChild(t);
      line = w; lineNo++;
    } else line=test;
  }
  if(line){
    const t = SVG('text',{x:12,y:48+lineNo*15,'font-size':11,fill:'var(--mute)'});
    t.textContent = line; panel.appendChild(t);
    lineNo++;
  }
  const bound = SVG('text',{x:12,y:48+(lineNo+1)*15,'font-size':11,fill:'var(--yellow)'});
  bound.textContent = cur.bound; panel.appendChild(bound);
  svg.appendChild(panel);
  const sumX = cur.x.reduce((a,b)=>a+b,0);
  out.textContent = `Step ${s}: Σ x_e = ${sumX.toFixed(2)}.`;
}
btnPrev.addEventListener('click', ()=>{ s = (s-1+STEPS.length)%STEPS.length; draw(); });
btnNext.addEventListener('click', ()=>{ s = (s+1)%STEPS.length; draw(); });
draw();
